INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65055155', 65055155, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian dan Evaluasi Pembangunan Jangka Menengah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 91800000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup pekerjaan Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian dan Evaluasi Pembangunan Jangka Menengah meliputi beberapa kegiatan yang mencakup: 1) Asistensi Penyusunan Rancangan Peraturan Menteri PPN/Kepala Bappenas tentang Pengendalian dan Evaluasi Pembangunan; 2) Asistensi Penyusunan Prosedur Evaluasi Pembangunan Jangka Menengah sebagai turunan dari Peraturan Menteri PPN/Kepala Bappenas yang telah disusun; 3) Asistensi Penyusunan Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional; serta 4) Monitoring dan Evaluasi Implementasi Peraturan Menteri PPN/Kepala Bappenas tentang Pengendalian dan Evaluasi Pembangunan termasuk prosedur turunannya. Adapun kegiatan tersebut terdiri atas tahapan Asistensi persiapan penyusunan, proses penyusunan dan pembahasan Draft, hingga penyampaian hasil akhir dokumen Peraturan Menteri PPN/Kepala Bappenas.', 'Keluaran kegiatan dari lingkup pekerjaan Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian dan Evaluasi Pembangunan Jangka Menengah adalah Laporan Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian dan Evaluasi Pembangunan Jangka Menengah dengan waktu penyelesaian selama 11 (sebelas) bulan. Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian dan Evaluasi Pembangunan Jangka Menengah dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko memiliki keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan hasil pendalaman substansi Rancangan Peraturan Menteri PPN/Kepala Bappenas dan kerangka substansi Prosedur Evaluasi Pembangunan Jangka Menengah 2 Termin 2 Laporan Draft Awal Rancangan Peraturan Menteri PPN/Kepala Bappenas dan Prosedur Evaluasi Pembangunan Jangka Menengah serta Kerangka substansi Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 3 Termin 3 Laporan Draft Rancangan Peraturan Menteri PPN/Kepala Bappenas dan Prosedur Evaluasi Pembangunan Jangka Menengah serta Draft Awal Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 4 Termin 4 Laporan Draft Rancangan Peraturan Menteri PPN/Kepala Bappenas dan Prosedur Evaluasi Pembangunan Jangka Menengah serta Draft Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 5 Termin 5 Laporan Dokumen Peraturan Menteri PPN/Kepala Bappenas hasil harmonisasi dan Prosedur Evaluasi Pembangunan Jangka Menengah serta Draft Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 6 Termin 6 Laporan Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian dan Evaluasi Pembangunan Jangka Menengah', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1900301);
