INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65057968', 65057968, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM33 KANTOR IMIGRASI KELAS II NON TPI MAMUJU', 'Pengadaan barang sice dan kursi besi metal kegiatan peralatan dan fasilitas perkantoran Pada Kantor Imigrasi Kelas II Non TPI Mamuju - Sulawesi Barat Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Sulawesi Barat, Mamuju (Kab.) | Sulawesi Barat, Mamuju (Kab.)', 136570000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '48 Unit', '46 Kursi besi aula serba guna 1.210.000 x 46 Bahan rangka dan konstruksi rangka kayu atau logam solid memberikan durabilitas bagus. Material busa/dudukan dan sandaran busa dengan densitas cukup untuk kenyamanan dan tahan lama (contoh:”High Density Foam”). Dudukan Cukup dalam, sandaran nyaman, dan lengan (armrest) cocok dengan posisi duduk. Pelapis/cover (Fabric, Kulit, kulit sintetis) 1 Kursi Gaming 5.910.000 Bahan Produk: Moulding Foam Adjustable Armrest Dimensi Produk: Ukuran Dudukan 51 x 57 cm TInggi kursi = 130 - 140 cm Spesifikasi Produk: Ergonomic Mekanis Double Stik Hidrolik up-down Moulding Foam Adjustable Armrest Kaki Besi (Gas + Cakar Chrome) Dimensi : Ukuran Dudukan 51 x 57 cm T kursi = 130 - 140 cm Sice: Material cover dudukan & sandaran: half leather Material kaki: metal Daya beban per seater: 100 kg Jenis: set sofa recliner Tinggi sandaran: 60 cm Tinggi kaki: 5 cm Memiliki fitur recliner electric Sandaran punggung dan penopang kaki dapat direbahkan Kualitas bantalan dudukan dan sandaran yang empuk Nyaman digunakan Rangka kokoh, kuat, dan stabil. Panjang sofa 1 dudukan: 110 cm Lebar sofa 1 dudukan: 85 cm Tinggi sofa 1 dudukan: 100 cm Panjang sofa 2 dudukan: 165 cm Lebar sofa 2 dudukan: 85 cm Tinggi sofa 2 dudukan: 100 cm Panjang sofa 3 dudukan: 230 cm Lebar sofa 3 dudukan: 85 cm Tinggi sofa 3 dudukan: 100 cm Dimensi produk: 230 cm x 250 cm x 100 cm Warna: Krem Dimensi Kemasan: 112.0 x 88.0 x 456.0 cm', '46 Kursi besi aula serba guna 1.210.000 x 46 Bahan rangka dan konstruksi rangka kayu atau logam solid. Material busa/dudukan dan sandaran busa dengan densitas cukup untuk kenyamanan dan tahan lama (contoh:”High Density Foam”). Dudukan Cukup dalam, sandaran nyaman, dan lengan (armrest) cocok dengan posisi duduk. Pelapis/cover (Fabric, Kulit, kulit sintetis) 1 Kursi Gaming 5.910.000 Bahan Produk: Moulding Foam Adjustable Armrest Dimensi Produk: Ukuran Dudukan 51 x 57 cm TInggi kursi = 130 - 140 cm Spesifikasi Produk: Ergonomic Mekanis Double Stik Hidrolik up-down Moulding Foam Adjustable Armrest Kaki Besi (Gas + Cakar Chrome) Dimensi : Ukuran Dudukan 51 x 57 cm T kursi = 130 - 140 cm Sice: Material cover dudukan & sandaran: half leather Material kaki: metal Daya beban per seater: 100 kg Jenis: set sofa recliner Tinggi sandaran: 60 cm Tinggi kaki: 5 cm Memiliki fitur recliner electric Sandaran punggung dan penopang kaki dapat direbahkan Kualitas bantalan dudukan dan sandaran yang empuk.', 76720000, 'high', 'Terdapat indikasi pengadaan furnitur yang kurang pantas untuk kantor layanan publik, khususnya sofa recliner elektrik dan kursi gaming, karena bersifat premium/kenyamanan personal dan tidak tampak esensial bagi fungsi perkantoran umum. Dari rincian yang tersedia, porsi biaya untuk 46 kursi aula tampak wajar, sedangkan sisa anggaran besar kemungkinan terserap pada item premium tersebut sehingga berpotensi menjadi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 1906754);
