INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65037389', 65037389, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Pengembangan Instrumen Pengendalian Perencanaan Dan Pelaksanaan Pembangunan Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi Dalam Kerangka Rencana Kerja Pemerintah (RKP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 245000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup Kegiatan untuk Jasa Konsultan Pengembangan Instrumen Pengendalian Perencanaan Dan Pelaksanaan Pembangunan Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi Dalam Kerangka Rencana Kerja Pemerintah (RKP), meliputi: A. Penguatan Ex-Ante (Pengendalian Perencanaan) - Advisory and Design 1. Mendesain struktur dan template executive summary (exsum) pengembangan ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 2. Menyusun panduan teknis pengisian Exsum dan data validation ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 3. Melakukan QA/peer review atas draf exsum, memberi rekomendasi perbaikan ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 4. Merumuskan risk taxonomy ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 5. Coaching on the job untuk tim Exsum ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 6. Menyusun SOP integrasi exsum ke siklus pengendalian triwulanan. Batasan: Konsultan tidak menyusun Exsum atas nama unit kerja, mendandatangani/menetapkan dokumen. B. Penguatan On Going (Pengendalian Pelaksanaan) - Mechanism Building and QA 1. Mendesain mekanisme forum pengendalian triwulanan ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 2. Co-Facilitation: memfasilitasi sisi teknis ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 3. Menyusun catatan teknis pendampingan & rekomendasi ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 4. Melakukan analisis risiko dinamis ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 5. Coaching on the job untuk tim pengendalian ruang lingkup Bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi. Batasan: Konsultan tidak menyusun Laporan Pengendalian Triwulanan resmi, dokumen formal ditetapkan oleh ASN.', 'Keluaran yang diharapkan dari kegiatan ini adalah: 1. Desain struktur dan template exsum pengembangan bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 2. Draf pedoman penyusunan executive summary bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; 3. Draf SOP pengendalian pembangunan triwulanan bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi; dan 4. Rekomendasi pengendalian perencanaan pembangunan RKP 2028. Adapun rincian keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut: Periode Output Termin 1 Laporan Rencana Kerja Pengendalian Perencanaan dan Pelaksanaan pembangunan bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi Termin 2 Laporan Struktur dan Implementasi Executive Summary bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi Termin 3 Laporan Update profil risiko bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi Termin 4 Laporan Integrasi Executive Summary dengan Critical Path bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi Termin 5 Laporan Akhir Pengembangan Instrumen Pengendalian Perencanaan dan Pelaksanaan bidang Infrastruktur, Peningkatan Lapangan Kerja, Kewirausahaan, Industri Kreatif, Dan Agromaritim Industri Melalui Koperasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1908837);
