INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65037395', 65037395, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Pengembangan Instrumen Pengendalian Perencanaan Dan Pelaksanaan Pembangunan Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri Dalam Kerangka Rencana Kerja Pemerintah (RKP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 245000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Lingkup Kegiatan untuk Jasa Konsultan Pengembangan Instrumen Pengendalian Perencanaan dan Pelaksanaan Pembangunan Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri Dalam Kerangka Rencana Kerja Pemerintah (RKP), meliputi: A. Penguatan Ex-Ante (Pengendalian Perencanaan) - Advisory & Design 1. Mendesain struktur dan template exsum (executive summary) pengembangan ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 2. Menyusun panduan teknis pengisian eksum dan data validation ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 3. Melakukan QA/peer review atas draf exsum, memberi rekomendasi perbaikan ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 4. Merumuskan risk taxonomy ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 5. Coaching on the job untuk tim Exsum ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 6. Menyusun SOP integrasi exsum ke siklus pengendalian triwulanan. Batasan: Konsultan tidak menyusun Exsum atas nama unit kerja, mendandatangani/menetapkan dokumen. B. Penguatan On Going (Pengendalian Pelaksanaan) - Mechanism Building & QA 1. Mendesain mekanisme forum pengendalian triwulanan ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 2. Co-Facilitation: memfasilitasi sisi teknis ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 3. Menyusun catatan teknis pendampingan & rekomendasi ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 4. Melakukan analisis risiko dinamis ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 5. Coaching on the job untuk tim pengendalian ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri. Batasan: Konsultan tidak menyusun Laporan Pengendalian Triwulanan resmi, dokumen formal ditetapkan oleh ASN.', 'Keluaran yang diharapkan dari kegiatan ini adalah: 1. Desain struktur dan template exsum pengembangan ruang lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 2. Draf pedoman penyusunan executive summary lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; 3. Draf SOP pengendalian pembangunan triwulanan lingkup Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri; dan 4. Rekomendasi pengendalian perencanaan pembangunan RKP 2028. Adapun rincian keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut: Periode Output Termin 1 Laporan Rencana Kerja Pengendalian Perencanaan dan Pelaksanaan Pembangunan Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri Termin 2 Laporan Struktur dan Implementasi Executive Summary Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri Termin 3 Laporan Update profil risiko Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri Termin 4 Laporan Integrasi Executive Summary dengan Critical Path Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri Termin 5 Laporan Akhir Pengembangan Instrumen Pengendalian Perencanaan dan Pelaksanaan Bidang Hilirisasi Serta Pengembangan Industri Berbasis Sumber Daya Alam Dalam Peningkatan Nilai Tambah Di Dalam Negeri', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1909609);
