INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65037160', 65037160, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Pengelolaan Kinerja Organisasi Lingkup Kedeputian Pengendalian, Evaluasi dan Manajemen Risiko Pembangunan', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 204000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Lingkup kegiatan untuk Jasa Konsultansi Pengelolaan Kinerja Organisasi Kedeputian Pengendalian, Evaluasi dan Manajemen Risiko Pembangunan meliputi: 1. Analisis Kematangan Pengelolaan Kinerja a. Inventarisasi praktik pengelolaan kinerja saat ini di lingkup kedeputian b. Penyusunan maturity model konseptual untuk menilai tingkat kematangan pengelolaan kinerja. c. Analisis kesenjangan antara praktik eksisting dan praktik ideal. 2. Penyusunan Model Konseptual Pengelolaan Kinerja Terintegrasi a. Penyusunan kerangka konseptual yang mengintegrasikan perencanaan, pengendalian, evaluasi kinerja, dan manajemen risiko pembangunan. b. Penyusunan logical framework / theory of change pengelolaan kinerja organisasi. c. Perancangan alur proses pengelolaan kinerja lintas fungsi dan unit kerja. 3. Pengembangan Toolkit Teknis Pengelolaan Kinerja a. Pembuatan perangkat bantu teknis (template pemetaan sasaran dan indikator, matriks keterkaitan kinerja-risiko, format monitoring capaian kinerja, dan mock-up dashboard). b. Penyusunan petunjuk teknis penggunaan toolkit. c. Uji coba terbatas secara konseptual dan penyempurnaan toolkit berdasarkan masukan internal. 4. Rekomendasi Penguatan Sistem Monitoring dan Evaluasi (Monev) a. Analisis sistem Monev yang berjalan dan identifikasi kelemahan.. b. Penyusunan alternatif desain penguatan Monev berbasis hasil (outcome), risiko pembangunan, dan integrasi lintas proses. c. Perumusan indikator kualitatif efektivitas sistem Monev. 5. Laporan Akhir Penguatan Pengelolaan Kinerja Organisasi Kedeputian', 'Keluaran yang diharapkan dari kegiatan ini adalah: 1. Dokumen Analisis Kematangan Pengelolaan Kinerja Lingkup Kedeputian Bidang Pengendalian, Evaluasi dan Manajemen Risiko. 2. Model Konseptual Pengelolaan Kinerja Terintegrasi 3. Toolkit Teknis Pengelolaan Kinerja beserta petunjuk penggunaan dan mock-up dashboard. 4. Rekomendasi Penguatan Sistem Monitoring dan Evaluasi (Monev) berbasis outcome dan risiko pembangunan 5. Laporan akhir penguatan Pengelolaan Kinerja Organisasi Kedeputian. Adapun rincian keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut: No Periode Keluaran per Termin 1 Termin I Laporan Pendahuluan yang memuat pemahaman awal terhadap ruang lingkup kegiatan, metodologi kerja, rencana pelaksanaan, dan jadwal kegiatan konsultansi. 2 Termin II Dokumen hasil analisis praktik pengelolaan kinerja eksisting, kerangka maturity model pengelolaan kinerja organisasi (konseptual) dan hasil gap analysis antara kondisi eksisting dan kondisi ideal. 3 Termin III Dokumen kerangka integrasi perencanaan kinerja, pengendalian, evaluasi kinerja, dan manajemen risiko pembangunan, Logical framework / theory of change pengelolaan kinerja organisasi dan Alur proses pengelolaan kinerja lintas fungsi dan unit kerja. 4 Termin IV Draft Toolkit Teknis Pengelolaan Kinerja dan Model Konseptual dan Toolkit Teknis Pengelolaan Kinerja Lingkup Kedeputian Bidang Pengendalian, Evaluasi dan Manajemen Risiko 5 Termin V Dokumen rekomendasi analisis kelemahan dan penguatan sistem Monev, Indikator kualitatif efektivitas sistem Monev 6 Termin VI Laporan Akhir Penguatan Pengelolaan Kinerja Organisasi Lingkup Kedeputian Bidang Pengendalian, Evaluasi dan Manajemen Risiko', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1909614);
