INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65037136', 65037136, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Penyusunan Kajian Penguatan Sistem dan Mekanisme Pengendalian serta Evaluasi dalam Penyusunan Revisi PP 39/2006', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 218350000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Lingkup Kegiatan untuk Jasa Konsultansi Penyusunan Kajian Penguatan Sistem dan Mekanisme Pengendalian serta Evaluasi dalam Penyusunan Revisi PP 39/2006, meliputi: 1. Identifikasi dan Analisis Tantangan Implementasi PP 39/2006 a. Analisis PP 39 Tahun 2006 beserta regulasi terkait (UU, PP, Perpres, Permen). b. Identifikasi isu, celah pengaturan, dan tantangan implementasi PP 39/2006. 2. Analisis Kelembagaan dan Mekanisme Pengendalian serta Evaluasi a. Analisis peran dan kewenangan kementerian/lembaga dan pemerintah daerah dalam pengendalian dan evaluasi. b. Analisis mekanisme pengendalian dan evaluasi (ex-ante, on-going, ex-post). 3. Perumusan Substansi Revisi a. Menyusun naskah urgensi revisi PP 39 Tahun 2006. b. Menyusun draf revisi PP 39 Tahun 2006. 4. Pelaksanaan Konsultasi dan Pendampingan a. Memberikan dukungan teknis dan substansi dalam pelaksanaan FGD dan konsultasi dengan K/L/D serta pemangku kepentingan terkait. b. Melakukan pendampingan dalam proses pembahasan Panitia Antarkementerian (PAK) dan Harmonisasi. c. Melakukan penyempurnaan terhadap draf naskah urgensi dan draf revisi berdasarkan masukan PAK dan Harmonisasi. 5. Finalisasi Dokumen a. Melakukan finalisasi penyusunan naskah urgensi dan draf revisi PP 39/2006. b. Menyusun laporan pelaksanaan revisi PP 39/2006.', '1. Draft Naskah Urgensi Revisi PP 39/2006 yang memuat Penguatan Sistem serta Mekanisme Pengendalian dan Evaluasi Pembangunan; dan 2. Draf Revisi PP 39/2006 yang mengatur Sistem serta Mekanisme Pengendalian dan Evaluasi Pembangunan. Rincian keluaran akan dilaporkan secara bertahap dalam 6 (enam) termin, sebagai berikut: No Periode Keluaran per Termin 1 Termin I Laporan Hasil Analisis Sistem, Kelembagaan, dan Mekanisme Koordinasi Eksisting sebagai bahan awal penyusunan Naskah Urgensi Revisi PP 39/2006 2 Termin II Laporan Rencana Perbaikan Sistem serta Mekanisme Pengendalian dan Evaluasi sebagai bahan awal penyusunan Naskah Urgensi Revisi PP 39/2006 3 Termin III Draft Awal Revisi PP 39/2006 dan Laporan Hasil Konsultasi Pemangku Kepentingan (Kementerian/Lembaga, Daerah, Akademisi, dan Pakar) 4 Termin IV Laporan hasil integrasi masukan rapat Panitia Antarkementerian (PAK) ke dalam draft awal Naskah Urgensi dan Draf Revisi PP 5 Termin V Laporan hasil integrasi masukan rapat Harmonisasi ke dalam draft Naskah Urgensi dan Draf Revisi PP II serta Surat permohonan penetapan kepada Presiden. 6 Termin VI Laporan Akhir yang memuat Rangkaian Proses Penyusunan Revisi PP 39/2006 dan dilengkapi dengan Draf Akhir Naskah Urgensi dan Revisi PP 39/2006', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1909949);
